<template><div class="detail-page"><el-card shadow="never" class="!border-none"><el-form :model="filters" inline class="filter-form"><el-form-item label="筛选搜索"><el-input v-model="filters.keyword" clearable placeholder="用户昵称 / 手机号" /></el-form-item><el-form-item label="变动时间"><el-date-picker v-model="filters.dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item><el-button type="primary" @click="resetPage">查询</el-button><el-button @click="resetFilters">重置</el-button><el-button :icon="Download" @click="exportData">导出</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="!border-none mt-4"><template #header><span class="card-title">积分明细</span></template><el-table :data="pagedRows" stripe table-layout="fixed"><el-table-column prop="recordId" label="记录ID" min-width="160" /><el-table-column prop="user" label="用户昵称" min-width="140" /><el-table-column prop="phone" label="手机号" min-width="140" /><el-table-column prop="reason" label="变动原因" min-width="190" /><el-table-column prop="amount" label="变动数额" min-width="110" /><el-table-column prop="after" label="变动后余额" min-width="120" /><el-table-column prop="createdAt" label="变动时间" min-width="170" /></el-table><div class="pagination"><el-pagination v-model:current-page="page" background layout="total, prev, pager, next" :total="filteredRows.length" /></div></el-card></div></template>
<script lang="ts" setup name="pointDetails">
import { Download } from '@element-plus/icons-vue'
const filters = reactive({ keyword: '', dateRange: [] as string[] }); const page = ref(1); const pageSize = 10; const users = ['小鹿用户', '青柠茶友', '山野拾光', '快乐汽水']
const rows = reactive<any[]>(Array.from({ length: 26 }, (_, i) => { const amount = i % 3 ? 100 : -50; return { recordId: `JF202608${String(10001 + i)}`, user: users[i % users.length], phone: `138****${String(1020 + i).slice(-4)}`, reason: amount > 0 ? '扫码获得积分' : '兑换商品扣减积分', amount: amount > 0 ? `+${amount}` : amount, after: 680 + i * 35, createdAt: `2026-08-${String(28 - i % 20).padStart(2, '0')} ${String(9 + i % 9).padStart(2, '0')}:20:00` } }))
const filteredRows = computed(() => rows.filter(r => { const inDate = filters.dateRange.length !== 2 || (r.createdAt.slice(0, 10) >= filters.dateRange[0] && r.createdAt.slice(0, 10) <= filters.dateRange[1]); return (!filters.keyword.trim() || `${r.user}${r.phone}`.includes(filters.keyword.trim())) && inDate })); const pagedRows = computed(() => filteredRows.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const resetPage = () => { page.value = 1 }; const resetFilters = () => { Object.assign(filters, { keyword: '', dateRange: [] }); resetPage() }
const exportData = () => { const data = [['记录ID', '用户昵称', '手机号', '变动原因', '变动数额', '变动后余额', '变动时间'], ...filteredRows.value.map(r => [r.recordId, r.user, r.phone, r.reason, r.amount, r.after, r.createdAt])]; const url = URL.createObjectURL(new Blob([`\ufeff${data.map(r => r.join(',')).join('\n')}`], { type: 'text/csv;charset=utf-8;' })); const a = document.createElement('a'); a.href = url; a.download = '积分明细.csv'; a.click(); URL.revokeObjectURL(url) }
</script><style scoped>.filter-form{margin-bottom:-18px}.filter-form :deep(.el-input){width:240px}.filter-form :deep(.el-date-editor){width:280px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}@media(max-width:700px){.filter-form :deep(.el-input),.filter-form :deep(.el-date-editor){width:100%}.filter-form :deep(.el-form-item){width:100%;margin-right:0}}</style>
